const RANGE={"ndvi":{"min":0.579,"max":0.82},"ndmi":{"min":0.111,"max":0.306},"ndre":{"min":0.378,"max":0.559}};

/* 11 stop come Barolo: mattone(stress) -> oro -> verde(vigore) */
function colore(val,ix){
  if(val==null)return '#333';
  const r=RANGE[ix];
  let t=Math.max(0,Math.min(1,(val-r.min)/(r.max-r.min||1)));
  t=Math.pow(t,1.3); // gamma: distende un po' la parte alta affollata senza scurire troppo
  const stops=[[0,[105,40,32]],[.08,[139,58,42]],[.16,[170,90,58]],[.24,[195,135,82]],
    [.33,[214,182,112]],[.42,[200,190,116]],[.51,[165,185,105]],[.60,[125,172,92]],
    [.69,[90,155,82]],[.78,[65,150,140]],[.87,[55,130,175]],[.93,[48,108,190]],[1,[38,80,178]]];
  for(let i=0;i<stops.length-1;i++){const[t0,c0]=stops[i],[t1,c1]=stops[i+1];
    if(t>=t0&&t<=t1){const f=(t-t0)/(t1-t0);
      return`rgb(${Math.round(c0[0]+f*(c1[0]-c0[0]))},${Math.round(c0[1]+f*(c1[1]-c0[1]))},${Math.round(c0[2]+f*(c1[2]-c0[2]))})`;}}
  return'#888';
}
function valore(vid,ix,anno){const v=DATI[vid];if(!v)return null;const y=v.y[anno];return(y&&y[ix]!=null)?y[ix]:null;}
function parola(val,ix){if(val==null)return'\u2014';for(const[s,t]of PAROLE[ix])if(val>=s)return t;return PAROLE[ix].slice(-1)[0][1];}
function etichetta(vid){const v=DATI[vid];if(!v)return'Cartizze . dato non disponibile';const c=v.c||'Cartizze';return v.q?`${c} . ${v.q} m`:c;}

function stile(vid){
  const sel = vid===vidSel;
  const v = DATI[vid];
  const storico = STORICI_SET.has(vid);
  const val=valore(vid,idxSel,annoSel);
  if(val==null)return{fillColor:'#333',fillOpacity:sel?0.45:0.2,color:sel?'#c9a84c':(storico?'#c9a84c':'#555'),weight:sel?3:(storico?1:0.5)};
  return{fillColor:colore(val,idxSel),
    fillOpacity:vidSel&&!sel?0.4:0.72,
    color:sel?'#f0d878':(storico?'#c9a84c':'#1a1a1a'),
    weight:sel?3:(storico?1:0.7)};
}

const CARTIZZE_BOUNDS=L.latLngBounds([45.7800,11.8843],[46.0269,12.3480]); /* allargato per includere le 26 Vigne storiche + margine 8km, apertura resta zoomata su Cartizze */
/* set dei vid nel gruppo "storico" letto da VIGNE (non da DATI.zona, che per la Rivetta resta 'Cartizze' perche' e' li' fisicamente) */
const STORICI_SET = new Set(VIGNE.features.filter(f=>f.properties.gruppo==='storico').map(f=>f.properties.vid));
function initMap(){
  map=L.map('map',{zoomControl:false,attributionControl:false,
    maxBounds:CARTIZZE_BOUNDS, maxBoundsViscosity:0.9, minZoom:11}).setView([45.896,12.031],15);
  L.tileLayer('https://mt0.google.com/vt/lyrs=s&hl=it&x={x}&y={y}&z={z}',{maxZoom:20,subdomains:['mt0','mt1','mt2','mt3']}).addTo(map);
  L.control.zoom({position:'bottomright'}).addTo(map);
  L.geoJSON(CONFINE,{style:{color:'#c9a84c',weight:2,fill:false,dashArray:'5,4',opacity:0.85}}).addTo(map);
  const TOOLTIP_MIN_ZOOM=16;
  L.geoJSON(VIGNE,{
    style:f=>stile(f.properties.vid),
    onEachFeature:(f,lyr)=>{const p=f.properties;layers[p.vid]=lyr;
      lyr.bindTooltip(etichetta(p.vid),{sticky:true,direction:'top'});
      lyr.on('mouseover',()=>{
        lyr.setStyle({weight:1.8,color:'#fff'});
        if(map.getZoom()<TOOLTIP_MIN_ZOOM) lyr.closeTooltip();
      });
      lyr.on('click',()=>selVigna(p.vid));
      lyr.on('mouseout',()=>lyr.setStyle(stile(p.vid)));}
  }).addTo(map);
  map.on('zoomend',()=>{
    if(map.getZoom()<TOOLTIP_MIN_ZOOM){for(const vid in layers)layers[vid].closeTooltip();}
  });
}
function ricolora(){for(const vid in layers)layers[vid].setStyle(stile(vid));aggLegenda();}

function aggLegenda(){
  document.getElementById('leg-title').textContent=NOMI_LUNGHI[idxSel];
  const r=RANGE[idxSel];
  document.getElementById('leg-lo').textContent='basso ('+r.min.toFixed(2)+')';
  document.getElementById('leg-hi').textContent='alto ('+r.max.toFixed(2)+')';
  const note=document.getElementById('leg-note');
  if(note) note.textContent='colori confrontabili tra tutti gli anni';
}

/* PANNELLO: vigne per contrada (come comuni/MGA di Barolo) */
function buildPanel(){
  const list=document.getElementById('comuni-list');

  /* --- gruppo VIGNE-MENZIONE: nomi diretti, no sotto-raggruppamento --- */
  const nomePulito=n=>(n||'').replace(/^(Vigna|Vigneto|Vinga)\s+/i,'');
  const storiche=VIGNE.features.filter(f=>f.properties.gruppo==='storico').map(f=>f.properties)
    .sort((a,b)=>nomePulito(a.nome_vigna||a.label).localeCompare(nomePulito(b.nome_vigna||b.label)));
  if(storiche.length){
    const macro=document.createElement('div');macro.className='macro-group storico';
    const macroHead=document.createElement('div');macroHead.className='macro-header collapsible';
    macroHead.innerHTML=`<span>Vigne-Menzione</span><span style="display:flex;align-items:center;gap:8px"><span style="color:var(--text-mute);font-size:10px">${storiche.length}</span><span class="macro-arrow">\u25B4</span></span>`;
    const macroNote=document.createElement('div');macroNote.className='macro-note';
    macroNote.textContent='nome ufficiale depositato per obbligo di etichetta';
    const vlist=document.createElement('div');vlist.className='mga-list open';
    storiche.forEach(p=>{const item=document.createElement('div');item.className='mga-item storico';
      item.textContent=nomePulito(p.nome_vigna||p.label);item.dataset.vid=p.vid;
      item.onclick=()=>selVigna(p.vid);
      vlist.appendChild(item);});
    macroHead.onclick=()=>{vlist.classList.toggle('open');macroHead.classList.toggle('collapsed');macroNote.style.display=vlist.classList.contains('open')?'':'none';};
    macro.appendChild(macroHead);macro.appendChild(macroNote);macro.appendChild(vlist);list.appendChild(macro);
  }

  /* --- gruppo CARTIZZE: contrade come prima --- */
  const macroCartizze=document.createElement('div');macroCartizze.className='macro-group cartizze';
  const macroHeadC=document.createElement('div');macroHeadC.className='macro-header';
  macroHeadC.innerHTML=`<span>Cartizze</span>`;
  macroCartizze.appendChild(macroHeadC);

  const byC={};
  VIGNE.features.filter(f=>f.properties.gruppo==='cartizze').forEach(f=>{
    const c=f.properties.contrada||'Senza contrada';(byC[c]=byC[c]||[]).push(f.properties);});
  Object.keys(byC).sort().forEach(c=>{
    const vigne=byC[c].sort((a,b)=>(DATI[b.vid]?.q||0)-(DATI[a.vid]?.q||0));
    const group=document.createElement('div');group.className='comune-group';
    const header=document.createElement('div');header.className='comune-header';
    const dot=`<span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:${CONTRADA_COL[c]||'#888'};margin-right:6px"></span>`;
    header.innerHTML=`<span>${dot}${c}</span><span style="color:var(--text-mute);font-size:10px">${vigne.length}</span>`;
    const vlist=document.createElement('div');vlist.className='mga-list';
    vigne.forEach(p=>{const item=document.createElement('div');item.className='mga-item';
      item.textContent=etichetta(p.vid);item.dataset.vid=p.vid;
      item.onclick=()=>selVigna(p.vid);
      vlist.appendChild(item);});
    header.onclick=()=>vlist.classList.toggle('open');
    group.appendChild(header);group.appendChild(vlist);macroCartizze.appendChild(group);
  });
  list.appendChild(macroCartizze);

  document.getElementById('search').oninput=e=>{
    const q=e.target.value.toLowerCase();
    document.querySelectorAll('.mga-item').forEach(it=>{
      const m=it.textContent.toLowerCase().includes(q);it.style.display=m?'':'none';
      if(m&&q)it.closest('.mga-list').classList.add('open');});
    if(!q)document.querySelectorAll('.mga-list').forEach(l=>l.classList.remove('open'));
  };
}

function buildYearBar(){
  const bar=document.getElementById('year-bar');
  ANNI.forEach(y=>{const b=document.createElement('button');
    b.className='yr-btn'+(y===annoSel?' active':'');b.textContent=y;
    b.onclick=()=>{annoSel=y;document.querySelectorAll('.yr-btn').forEach(x=>x.classList.remove('active'));
      b.classList.add('active');ricolora();if(vidSel)aggDrawer();};
    bar.appendChild(b);});
}

function initTabs(){
  document.querySelectorAll('.tab-btn').forEach(b=>{b.onclick=()=>{idxSel=b.dataset.idx;
    document.querySelectorAll('.tab-btn').forEach(x=>x.classList.remove('active'));
    b.classList.add('active');ricolora();if(vidSel)aggDrawer();};});
}

function centraSu(vid){
  const lyr=layers[vid]; if(!lyr)return;
  const isMobile=window.innerWidth<=768;
  const drawerW=isMobile?0:385;
  map.fitBounds(lyr.getBounds(),{
    paddingTopLeft:[60,60],
    paddingBottomRight:[drawerW+40,isMobile?120:60],
    maxZoom:16
  });
}
function selVigna(vid){
  vidSel=vid;
  document.getElementById('drawer').classList.add('open');
  document.getElementById('legend').style.display='none';
  ricolora();              // ridisegna con evidenziamento
  document.querySelectorAll('.mga-item').forEach(it=>it.classList.toggle('sel',it.dataset.vid===vid));
  centraSu(vid);
  aggDrawer();
}
function aggDrawer(){
  const vid=vidSel,v=DATI[vid];
  if(!v){
    document.getElementById('drawer-title').textContent='Cartizze';
    document.getElementById('drawer-subtitle').textContent='dato satellite non disponibile per questa parcella';
    document.getElementById('read-label').textContent='';
    document.getElementById('br-value').textContent='\u2014';
    document.getElementById('br-word').textContent='\u2014';
    document.getElementById('and-label').textContent='';
    const badge=document.getElementById('year-badges');if(badge)badge.innerHTML='';
    const g=document.getElementById('morfo-grid');if(g)g.innerHTML='';
    if(chart){chart.destroy();chart=null;}
    return;
  }
  document.getElementById('drawer-title').textContent=v.c||'Cartizze';
  const sub=(v.q?`${v.q} m s.l.m. \u00b7 `:'')+`${v.a} ha`;
  document.getElementById('drawer-subtitle').textContent=sub;

  /* box immagine bottiglia, solo per le vigne storiche (nome pubblico noto) */
  let bottleBox=document.getElementById('bottle-box');
  if(STORICI_SET.has(vid)){
    if(!bottleBox){
      bottleBox=document.createElement('div'); bottleBox.id='bottle-box';
      const titleBlock=document.querySelector('.dh-titleblock');
      titleBlock.insertBefore(bottleBox, titleBlock.firstChild);
    }
    bottleBox.style.display='flex';
    bottleBox.innerHTML='';
    const img=document.createElement('img');
    img.src='Image/'+vid+'.jpg';
    img.alt='';
    img.onerror=function(){ bottleBox.innerHTML='<div id="bottle-placeholder">\u{1F37E}</div>'; };
    bottleBox.appendChild(img);
  } else if(bottleBox){
    bottleBox.style.display='none';
  }

  const val=valore(vid,idxSel,annoSel);
  document.getElementById('read-label').textContent=NOMI_LUNGHI[idxSel]+' nel '+annoSel;
  document.getElementById('br-value').textContent=val==null?'\u2014':val.toFixed(2);
  document.getElementById('br-word').textContent=parola(val,idxSel);
  document.getElementById('and-label').textContent='Andamento '+NOMI[idxSel]+' 2017\u20132025';
  // badge: anno migliore e peggiore per questo indice
  const serie=ANNI.map(a=>({a,val:v.y[a]?v.y[a][idxSel]:null})).filter(x=>x.val!=null);
  const badge=document.getElementById('year-badges');
  if(badge&&serie.length){
    const best=serie.reduce((m,x)=>x.val>m.val?x:m);
    const worst=serie.reduce((m,x)=>x.val<m.val?x:m);
    badge.innerHTML=`<span class="ybadge up">migliore: ${best.a}</span>`+
                    `<span class="ybadge dn">peggiore: ${worst.a}</span>`;
  }
  morfo(vid);grafico(vid);
}
document.getElementById('drawer-close').onclick=()=>{document.getElementById('drawer').classList.remove('open');document.getElementById('legend').style.display='';vidSel=null;ricolora();};

function pendParola(g){if(g==null)return'\u2014';if(g<8)return'dolce';if(g<18)return'media';if(g<26)return'ripida';return'molto ripida';}
function espParola(e){const m={'S':'Sud','SE':'Sud-est','SO':'Sud-ovest','E':'Est','O':'Ovest','N':'Nord','NE':'Nord-est','NO':'Nord-ovest'};return m[e]||e;}
function morfo(vid){
  const v=DATI[vid];const g=document.getElementById('morfo-grid');
  const dlt=(v.delta&&v.delta[idxSel]!=null)?v.delta[idxSel]:null;
  let dltTxt,dltSub;
  if(dlt==null){dltTxt='\u2014';dltSub='';}
  else if(Math.abs(dlt)<0.008){dltTxt='in media';dltSub='come il resto del Cartizze';}
  else if(dlt>0){dltTxt='+'+dlt.toFixed(3);dltSub='sopra la media Cartizze';}
  else{dltTxt=dlt.toFixed(3);dltSub='sotto la media Cartizze';}
  const espAff = v.pend!=null && v.pend>=8;  // sotto 8° l'esposizione e' poco attendibile
  const espVal = v.esp?espParola(v.esp):'\u2014';
  const espSub = !v.esp?'' : (espAff?'prevalente':'versante quasi piano, indicativa');
  const cells=[
    ['Quota media', v.q?v.q+'<small> m slm</small>':'\u2014','media del versante'],
    ['Pendenza', v.pend!=null?pendParola(v.pend)+' <small>('+v.pend+'\u00b0)</small>':'\u2014','del versante'],
    ['Esposizione', espVal, espSub],
    ['Confronto', dltTxt, dltSub],
  ];
  g.innerHTML=cells.map(([l,val,sub])=>`<div class="morfo-card"><div class="mc-label">${l}</div><div class="mc-val">${val}</div>${sub?`<div class="mc-sub">${sub}</div>`:''}</div>`).join('');
}

function grafico(vid){
  const v=DATI[vid],ctx=document.getElementById('chart');
  if(chart)chart.destroy();
  const serie=ANNI.map(a=>v.y[a]?v.y[a][idxSel]:null);
  // media Cartizze dell'indice per anno
  const media=ANNI.map(a=>{const vals=[];for(const k in DATI){const y=DATI[k].y[a];if(y&&y[idxSel]!=null)vals.push(y[idxSel]);}return vals.length?vals.reduce((s,x)=>s+x,0)/vals.length:null;});
  // anno selezionato evidenziato: lega numero+parola del riquadro al punto sul grafico
  const iSel=ANNI.indexOf(annoSel);
  const valSel=valore(vid,idxSel,annoSel);
  const ptRadius=ANNI.map((a,i)=>i===iSel?6:3);
  const ptColor=ANNI.map((a,i)=>i===iSel?'#f0d878':'#c9a84c');
  // banda orizzontale = soglia della fascia interpretativa in cui cade il valore selezionato
  const soglie=PAROLE[idxSel];
  let lo=0,hi=1;
  if(valSel!=null)for(let i=0;i<soglie.length;i++){if(valSel>=soglie[i][0]){hi=(i>0?soglie[i-1][0]:1);lo=soglie[i][0];break;}}
  const bandPlugin={id:'band',beforeDatasetsDraw(c){
    if(valSel==null)return;const{ctx,chartArea:ca,scales}=c;const yT=scales.y.getPixelForValue(hi),yB=scales.y.getPixelForValue(lo);
    ctx.save();ctx.fillStyle='rgba(201,168,76,.10)';ctx.fillRect(ca.left,yT,ca.right-ca.left,yB-yT);
    const yV=scales.y.getPixelForValue(valSel);ctx.strokeStyle='rgba(240,216,120,.55)';ctx.setLineDash([3,3]);ctx.lineWidth=1;
    ctx.beginPath();ctx.moveTo(ca.left,yV);ctx.lineTo(ca.right,yV);ctx.stroke();ctx.restore();}};
  chart=new Chart(ctx,{type:'line',
    data:{labels:ANNI,datasets:[
      {label:'questa vigna',data:serie,borderColor:'#c9a84c',backgroundColor:'rgba(201,168,76,.1)',tension:.3,spanGaps:true,pointRadius:ptRadius,pointBackgroundColor:ptColor,pointBorderColor:ptColor},
      {label:'media Cartizze',data:media,borderColor:'#8b2a2a',borderDash:[4,4],tension:.3,pointRadius:0}
    ]},
    options:{responsive:true,maintainAspectRatio:false,
      plugins:{legend:{labels:{color:'#8a8478',font:{size:10}}},
        tooltip:{callbacks:{afterBody:(items)=>{const it=items[0];if(it&&it.datasetIndex===0&&it.parsed.y!=null)return parola(it.parsed.y,idxSel);}}}},
      scales:{x:{ticks:{color:'#8a8478',font:{size:9}},grid:{color:'rgba(255,255,255,.04)'}},
              y:{ticks:{color:'#8a8478',font:{size:9}},grid:{color:'rgba(255,255,255,.04)'}}}},
    plugins:[bandPlugin]});
}

initMap();buildPanel();buildYearBar();initTabs();aggLegenda();
